// Some portions generated by Claude Code

// Row stores start in the page's memory and move to browser storage (IndexedDB, through the row-store worker) only
// once they grow past a limit, so a page never waits on browser storage to show an ordinary result. Safari can leave
// IndexedDB held by a frozen background tab; such a wait would otherwise never end.

const test = require('node:test');
const assert = require('node:assert/strict');
const { MemoryWorker, loadApi } = require('./query-load-more-harness.js');

function rows(from, to, pad = '') {
    return Array.from({ length: to - from }, (_, index) => [{ kind: 'literal', value: String(from + index) + pad }]);
}

function values(batch) {
    return [...batch].map((row) => row[0].value);
}

function countingFactory(make = () => new MemoryWorker()) {
    const workers = [];
    const factory = () => { const worker = make(); workers.push(worker); return worker; };
    return { workers, factory };
}

/** Lets the worker and the store answer what they owe. */
async function settle(rounds = 20) {
    for (let index = 0; index < rounds; index++) await new Promise((resolve) => setImmediate(resolve));
}

/** Waits until the store has moved its rows to browser storage (or gave up). */
async function moved(store, rounds = 100) {
    for (let index = 0; index < rounds && store.inMemory; index++) await new Promise((resolve) => setImmediate(resolve));
}

/** A worker whose browser storage answers only once open() is called, as IndexedDB held up by other work. */
class GatedWorker extends MemoryWorker {
    constructor() {
        super();
        this.held = [];
        this.opened = false;
    }
    postMessage(message) {
        if (this.opened) {
            super.postMessage(message);
        } else {
            this.held.push(message);
        }
    }
    open() {
        this.opened = true;
        this.held.splice(0).forEach((message) => super.postMessage(message));
    }
}

/** A worker whose browser storage never answers, as IndexedDB held by a frozen tab: requests wait forever. */
class SilentWorker extends MemoryWorker {
    postMessage(message) {
        this.messages.push(message);
    }
}

/** A worker whose IndexedDB cannot be opened: it answers every request like queryStreamWorker does then. */
class UnavailableStorageWorker extends MemoryWorker {
    postMessage(message) {
        this.messages.push(message);
        queueMicrotask(() => {
            const response = { requestId: message.requestId, ok: false, unavailable: true,
                error: 'IndexedDB is unavailable for Workbench query results.' };
            for (const callback of this.listeners.get('message') || []) callback({ data: response });
        });
    }
}

test('a row store keeps its rows in memory and starts no worker while it is under the spill limit', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory();
    assert.equal(api.SPILL_ROW_LIMIT, 10000);
    assert.equal(api.SPILL_BYTE_LIMIT, 32 * 1024 * 1024);
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 5 });
    assert.equal(store.inMemory, true);
    assert.equal(await store.append(rows(0, 5)), 5);
    assert.deepEqual(values(await store.read(1, 2)), ['1', '2']);
    assert.equal(await store.count(), 5);
    assert.equal(await store.truncate(3), 3);
    await store.dispose();
    assert.equal(workers.length, 0, 'an ordinary result never touches browser storage');
});

test('a row store moves its rows to browser storage once it grows past the spill row limit', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory();
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 3 });
    assert.equal(await store.append(rows(0, 3)), 3);
    assert.equal(workers.length, 0, 'at the limit the rows stay in memory');
    assert.equal(await store.append(rows(3, 5)), 5);
    await moved(store);
    assert.equal(store.inMemory, false);
    assert.equal(workers.length, 1);
    assert.equal(workers[0].messages[0].op, 'create');
    assert.deepEqual(values(workers[0].rows), ['0', '1', '2', '3', '4'], 'the rows held in memory are moved first');
    assert.deepEqual(values(await store.read(2, 3)), ['2', '3', '4']);
    assert.equal(await store.count(), 5);
    assert.equal(await store.append(rows(5, 6)), 6);
    assert.equal(await store.truncate(2), 2);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1']);
    await store.dispose();
    assert.equal(workers[0].messages.some((message) => message.op === 'dispose'), true);
    assert.equal(workers[0].terminated, true);
});

test('a row store also moves to browser storage once its rows grow past the spill byte limit', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory();
    const store = await api.createRowStore({ workerFactory: factory, spillByteLimit: 4000 });
    assert.equal(await store.append(rows(0, 2, 'x'.repeat(1000))), 2);
    assert.equal(workers.length, 0);
    assert.equal(await store.append(rows(2, 6, 'x'.repeat(1000))), 6);
    await moved(store);
    assert.equal(store.inMemory, false, 'six rows of about a kilobyte are past a 4000-byte limit');
    assert.equal(workers[0].rows.length, 6);
    await store.dispose();
});

test('a row store keeps the order of appends made while it moves to browser storage', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory();
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 2 });
    const counts = await Promise.all([store.append(rows(0, 2)), store.append(rows(2, 4)), store.append(rows(4, 5)),
        store.read(0, 5)]);
    assert.deepEqual(counts.slice(0, 3), [2, 4, 5]);
    assert.deepEqual(values(counts[3]), ['0', '1', '2', '3', '4']);
    await moved(store);
    assert.deepEqual(values(workers[0].rows), ['0', '1', '2', '3', '4']);
    await store.dispose();
});

// Safari can be slow to answer for a while (other tabs keep IndexedDB of the origin busy): the result keeps streaming
// into memory meanwhile, and moves once browser storage answers.
test('while browser storage is slow, rows keep going to memory without waiting, and move once it answers', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory(() => new GatedWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 2 });
    assert.equal(await store.append(rows(0, 2)), 2);
    const started = Date.now();
    assert.equal(await store.append(rows(2, 5)), 5, 'past the spill limit the rows still go to memory');
    assert.equal(await store.append(rows(5, 6)), 6);
    assert.ok(Date.now() - started < 1000, 'the page does not wait for browser storage');
    assert.equal(store.inMemory, true);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1', '2', '3', '4', '5']);
    assert.equal(workers.length, 1, 'one move at a time');
    workers[0].open();
    await moved(store);
    assert.equal(store.inMemory, false);
    assert.deepEqual(values(workers[0].rows), ['0', '1', '2', '3', '4', '5'], 'the rows that came meanwhile move too');
    assert.equal(await store.append(rows(6, 7)), 7);
    assert.deepEqual(values(await store.read(5, 5)), ['5', '6']);
    await store.dispose();
});

test('when memory is full, appends wait for browser storage instead of failing', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory(() => new GatedWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 1, memoryRowLimit: 3 });
    assert.equal(await store.append(rows(0, 2)), 2);
    let settled = false;
    const waiting = store.append(rows(2, 5)).then((count) => { settled = true; return count; });
    const after = store.append(rows(5, 6));
    await settle();
    assert.equal(settled, false, 'a full memory waits for browser storage');
    workers[0].open();
    assert.equal(await waiting, 5);
    assert.equal(await after, 6, 'later appends keep their order');
    assert.deepEqual(values(workers[0].rows), ['0', '1', '2', '3', '4', '5']);
    await store.dispose();
});

test('when memory is full and browser storage does not answer in time, the append fails and says so', async () => {
    const { api, window } = loadApi();
    const { workers, factory } = countingFactory(() => new SilentWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 1, memoryRowLimit: 3,
        storageTimeout: 20 });
    assert.equal(await store.append(rows(0, 2)), 2);
    const error = await store.append(rows(2, 5)).then(() => null, (failure) => failure);
    assert.match(error.message, /Browser storage did not answer in time, so the Workbench keeps at most 3 rows in memory/);
    assert.equal(error.code, 'storage', 'the page can offer to reset browser storage');
    assert.equal(await store.count(), 2);
    assert.deepEqual(values(await store.read(0, 5)), ['0', '1']);
    assert.equal(workers[0].terminated, true, 'the worker waiting on browser storage is closed');
    const id = workers[0].messages.find((message) => message.op === 'create').storeId;
    assert.equal(JSON.parse(window.localStorage.getItem('rdf4j.workbench.row-store.v2:' + id)).dispose, true);
    await store.dispose();
});

test('a truncate while the rows move keeps the stored copy in step', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory(() => new GatedWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 1 });
    await store.append(rows(0, 5));
    workers[0].open();
    assert.equal(await store.truncate(2), 2);
    await store.append(rows(10, 12));
    await moved(store);
    assert.equal(store.inMemory, false);
    assert.deepEqual(values(await store.read(0, 10)), ['0', '1', '10', '11']);
    assert.deepEqual(values(workers[0].rows), ['0', '1', '10', '11']);
    await store.dispose();
});

test('a move to browser storage that fails keeps the rows in memory, within the memory limit', async () => {
    const { api } = loadApi();
    const { workers, factory } = countingFactory(() => new UnavailableStorageWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 1, memoryRowLimit: 4 });
    assert.equal(await store.append(rows(0, 3)), 3);
    await settle();
    assert.equal(store.inMemory, true);
    assert.equal(workers[0].terminated, true);
    assert.equal(workers.length, 1, 'storage that cannot be opened is not tried again');
    const error = await store.append(rows(3, 5)).then(() => null, (failure) => failure);
    assert.match(error.message,
        /Browser storage is unavailable here, so the Workbench keeps at most 4 rows in memory\. Add a LIMIT/);
    assert.equal(error.code, 'storage');
    assert.equal(await store.count(), 3, 'a batch that does not fit is not kept in part');
    await store.dispose();
});

test('memory holds at most 1,000,000 rows and 128 MB of estimated row size', async () => {
    const { api } = loadApi();
    assert.equal(api.MEMORY_ROW_STORE_LIMIT, 1000000);
    assert.equal(api.MEMORY_BYTE_LIMIT, 128 * 1024 * 1024);
    const { factory } = countingFactory(() => new UnavailableStorageWorker());
    const store = await api.createRowStore({ workerFactory: factory, spillRowLimit: 1, memoryByteLimit: 3000 });
    assert.equal(await store.append(rows(0, 2, 'x'.repeat(1000))), 2);
    await settle();
    await assert.rejects(store.append(rows(2, 4, 'x'.repeat(1000))),
        /Browser storage is unavailable here, so the Workbench keeps at most 3 KB of rows in memory/);
    assert.equal(await store.count(), 2);
    await store.dispose();
});

// A database that fails (for example one the browser reports as corrupt) is not the end of browser storage: the
// store is flagged for cleanup and a fresh database is tried once.
test('a stored result whose database fails is replaced by a fresh one once', async () => {
    const { api, window } = loadApi();
    class BrokenWorker extends MemoryWorker {
        postMessage(message) {
            this.messages.push(message);
            queueMicrotask(() => {
                for (const callback of this.listeners.get('message') || []) {
                    callback({ data: { requestId: message.requestId, ok: false,
                        error: 'UnknownError: Database corrupt' } });
                }
            });
        }
    }
    const { workers, factory } = countingFactory();
    const make = [() => new BrokenWorker(), () => new MemoryWorker()];
    const store = await api.createRowStore({ workerFactory: () => { const worker = make.shift()(); workers.push(worker);
        return worker; }, spillRowLimit: 1 });
    await store.append(rows(0, 3));
    await moved(store);
    assert.equal(store.inMemory, false, 'the second database takes the rows');
    assert.equal(workers.length, 2);
    assert.deepEqual(values(workers[1].rows), ['0', '1', '2']);
    const broken = workers[0].messages.find((message) => message.op === 'create').storeId;
    assert.equal(JSON.parse(window.localStorage.getItem('rdf4j.workbench.row-store.v2:' + broken)).dispose, true,
        'the failed database is left to cleanup');
    assert.ok(factory);
    await store.dispose();
});
